#!/bin/sh
set -eu
umask 077
python3 -I -B - <<'INSTALL_NEUTRAL_OPAQUE'
import base64,hashlib,os,platform,zlib
from pathlib import Path
assert os.geteuid()==0 and platform.system()=='Linux'
raw=zlib.decompress(base64.b64decode('',validate=True))
assert len(raw)==5979 and hashlib.sha256(raw).hexdigest()=='f3c386972d8f4d91603a4d6dcd71aa48fcc03651efca60165bf7162de116325d'
p=Path('/root/t44-r9/neutral-opaque-r29-01.py');assert p.parent.resolve()==p.parent
fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o444)
with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
print('NEUTRAL_OPAQUE_TOOL_INSTALLED_ONLY')
INSTALL_NEUTRAL_OPAQUE
